import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, seq, active
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0 or o['side'] != 'buy':
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0 or o['side'] != 'sell':
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        incoming_price = price

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                top_price, top_seq, top_oid = sell_heap[0]
                resting = book[top_oid]
                if typ != 'market' and top_price > incoming_price:
                    break
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, top_oid, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    resting['active'] = False
                else:
                    heapq.heappush(sell_heap, (resting['price'], resting['seq'], top_oid))
        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negprice, top_seq, top_oid = buy_heap[0]
                resting = book[top_oid]
                top_price = -negprice
                if typ != 'market' and top_price < incoming_price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, resting['qty'])
                trades.append([top_oid, oid, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    resting['active'] = False
                else:
                    heapq.heappush(buy_heap, (-resting['price'], resting['seq'], top_oid))

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # ioc/market remainder discarded, or limit fully filled
            if typ == 'limit':
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

    return trades

